// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));
        vm.assume(caller.code.length == 0);

        // Ensure contract is not paused initially
        assertTrue(!c.paused());

        // Attempt ownership transfer to the caller
        vm.prank(c.owner());
        c.transferOwnership(caller);

        // Caller accepts ownership
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("acceptOwnership()"));

        // If acceptOwnership succeeded, paused must still be false
        // because no pause was ever called and the bug makes paused() return true
        assertTrue(!success || !c.paused());
    }
}

